import { EventEmitter } from 'node:events';
import { Readable } from 'node:stream';
async function main(): Promise<void> {
  const e: any = new EventEmitter();
  const log: string[] = [];
  const a = (async () => { await e.setMaxListeners(1); log.push('a1'); await e.setMaxListeners(2); log.push('a2'); })();
  const b = (async () => { await e.setMaxListeners(3); log.push('b1'); await e.setMaxListeners(4); log.push('b2'); })();
  await a; await b;
  console.log(log.join(','));
  // a JS promise settled by an AOT timer, awaited next to native promise jobs
  const r: JsValue = new Readable({ read() {} }) as JsValue;
  const order: string[] = [];
  setTimeout(() => { r.push('x'); r.push(null); }, 5);
  const t = (async () => { const v: JsValue = await r.toArray(); order.push("js:" + String(v.length)); })();
  const n = (async () => { await Promise.resolve(); order.push('native1'); await Promise.resolve(); order.push('native2'); })();
  await t; await n;
  console.log(order.join(','));
}
